diff --git a/packages/api/src/routes/health.ts b/packages/api/src/routes/health.ts
new file mode 100644
--- /dev/null
+++ b/packages/api/src/routes/health.ts
@@ -0,0 +1,22 @@
+import { json, unauthorized } from "../responses";
+import { requireToken } from "../auth";
+import type { Route } from "../types";
+
+const STARTED_AT = Date.now();
+
+export function healthRoute(): Route {
+  return {
+    method: "GET",
+    path: "/api/health",
+    handler: (req) => {
+      if (!requireToken(req)) {
+        return unauthorized();
+      }
+      return json({ ok: true, uptimeMs: Date.now() - STARTED_AT });
+    },
+  };
+}
+
+export function routes(): Route[] {
+  return [healthRoute()];
+}

